export function _hasOwnProp(obj: any, key: string) {
    return !!obj && Object.prototype.hasOwnProperty.call(obj, key)
}

export function _mergeTopLevelTransformControls(props: any, transform: any = {}) {
    const merged = { ...(transform || {}) }
    if (_hasOwnProp(props, "modelScale")) merged.scale = props.modelScale
    if (_hasOwnProp(props, "modelPosition"))
        merged.position = props.modelPosition
    if (_hasOwnProp(props, "modelRotation"))
        merged.rotation = props.modelRotation
    return merged
}

export function _mergeTopLevelAppearControls(props: any) {
    const dissolve = { ...(props?.dissolveTransition || {}) }
    const transform = { ...(dissolve.transform || {}) }
    if (_hasOwnProp(props, "appearReplay")) dissolve.replay = props.appearReplay
    if (_hasOwnProp(props, "appearTransformScale"))
        transform.scale = props.appearTransformScale
    if (_hasOwnProp(props, "appearTransformPosition"))
        transform.position = props.appearTransformPosition
    if (_hasOwnProp(props, "appearTransformRotation"))
        transform.rotation = props.appearTransformRotation
    return {
        ...dissolve,
        transform,
    }
}

export function _mergeTopLevelScrollTransformControls(props: any) {
    const position = props?.position || {}
    const scrollTarget = { ...(position.scrollTarget || {}) }
    const mobileScrollTarget = { ...(position.mobileScrollTarget || {}) }

    position.scrollTransform = true
    if (_hasOwnProp(props, "scrollTransformMatch"))
        position.scrollTransformMatch = props.scrollTransformMatch
    if (_hasOwnProp(props, "scrollTransformAnchor"))
        position.scrollAnchorY = props.scrollTransformAnchor
    if (_hasOwnProp(props, "scrollTransformScale"))
        scrollTarget.scale = props.scrollTransformScale
    if (_hasOwnProp(props, "scrollTransformPosition"))
        scrollTarget.position = props.scrollTransformPosition
    if (_hasOwnProp(props, "scrollTransformRotation"))
        scrollTarget.rotation = props.scrollTransformRotation

    return {
        ...position,
        scrollTarget,
        mobileScrollTarget,
    }
}

export function _mergeTopLevelRuntimeControls(props: any, transform: any = {}) {
    const isRoleGroup = props?.role === "group"
    return {
        ...props,
        asGroup: isRoleGroup || !!props?.asGroup,
        transform: _mergeTopLevelTransformControls(props, transform),
        dissolveTransition: _mergeTopLevelAppearControls(props),
        position: _mergeTopLevelScrollTransformControls(props),
    }
}

export function _parseCommaVector3(value: any, fallback = { x: 0, y: 0, z: 0 }) {
    if (Array.isArray(value)) {
        return {
            x: Number.isFinite(Number(value[0]))
                ? Number(value[0])
                : fallback.x,
            y: Number.isFinite(Number(value[1]))
                ? Number(value[1])
                : fallback.y,
            z: Number.isFinite(Number(value[2]))
                ? Number(value[2])
                : fallback.z,
        }
    }

    if (value && typeof value === "object") {
        return {
            x: Number.isFinite(Number(value.x)) ? Number(value.x) : fallback.x,
            y: Number.isFinite(Number(value.y)) ? Number(value.y) : fallback.y,
            z: Number.isFinite(Number(value.z)) ? Number(value.z) : fallback.z,
        }
    }

    if (typeof value !== "string") return fallback
    const parts = value
        .trim()
        .split(/[\s,]+/)
        .map((part) => Number(part))
    return {
        x: Number.isFinite(parts[0]) ? parts[0] : fallback.x,
        y: Number.isFinite(parts[1]) ? parts[1] : fallback.y,
        z: Number.isFinite(parts[2]) ? parts[2] : fallback.z,
    }
}

export function resolveThreeJSRuntimeTransform(transform: any, options: any = {}) {
    const width =
        typeof options === "number" ? options : Number(options?.width || 0)
    const forcedMobile =
        typeof options === "boolean" ? options : options?.useMobile
    const desktop = transform?.desktop ?? transform ?? {}
    const breakpoint = transform?.breakpoint ?? 768
    const useMobile =
        forcedMobile !== undefined
            ? !!forcedMobile
            : !!width && width <= breakpoint

    const desktopPosition = _parseCommaVector3(desktop.position, {
        x: desktop.offX ?? 0,
        y: desktop.offY ?? 0,
        z: desktop.offZ ?? 0,
    })
    const desktopRotation = _parseCommaVector3(desktop.rotation, {
        x: desktop.rotX ?? 0,
        y: desktop.rotY ?? 0,
        z: desktop.rotZ ?? 0,
    })
    const desktopResolved = {
        ...desktop,
        offX: desktopPosition.x,
        offY: desktopPosition.y,
        offZ: desktopPosition.z,
        rotX: desktopRotation.x,
        rotY: desktopRotation.y,
        rotZ: desktopRotation.z,
    }
    if (!useMobile) return desktopResolved

    const nestedMobile = transform?.mobile ?? {}
    const mobilePosition = _parseCommaVector3(
        transform?.mobilePosition ?? nestedMobile.position,
        {
            x: transform?.mobileOffX ?? nestedMobile.offX,
            y: transform?.mobileOffY ?? nestedMobile.offY,
            z: transform?.mobileOffZ ?? nestedMobile.offZ,
        }
    )
    const mobileRotation = _parseCommaVector3(
        transform?.mobileRotation ?? nestedMobile.rotation,
        {
            x: transform?.mobileRotX ?? nestedMobile.rotX,
            y: transform?.mobileRotY ?? nestedMobile.rotY,
            z: transform?.mobileRotZ ?? nestedMobile.rotZ,
        }
    )
    const mobile = {
        enabled: transform?.mobileEnabled ?? nestedMobile.enabled,
        scale: transform?.mobileScale ?? nestedMobile.scale,
        offX: mobilePosition.x,
        offY: mobilePosition.y,
        offZ: mobilePosition.z,
        rotX: mobileRotation.x,
        rotY: mobileRotation.y,
        rotZ: mobileRotation.z,
    }
    if (!mobile.enabled) return desktopResolved
    return {
        ...desktopResolved,
        ...mobile,
        scale: mobile.scale ?? desktopResolved.scale,
        offX: mobile.offX ?? desktopResolved.offX,
        offY: mobile.offY ?? desktopResolved.offY,
        offZ: mobile.offZ ?? desktopResolved.offZ,
        rotX: mobile.rotX ?? desktopResolved.rotX,
        rotY: mobile.rotY ?? desktopResolved.rotY,
        rotZ: mobile.rotZ ?? desktopResolved.rotZ,
    }
}

export function resolveThreeJSRuntimeSubSceneItem(item: any) {
    if (!item) return item
    const position = _parseCommaVector3(item.position, {
        x: item.offX ?? 0,
        y: item.offY ?? 0,
        z: item.offZ ?? 0,
    })
    const rotation = _parseCommaVector3(item.rotation, {
        x: item.rotX ?? 0,
        y: item.rotY ?? 0,
        z: item.rotZ ?? 0,
    })
    return {
        ...item,
        offX: position.x,
        offY: position.y,
        offZ: position.z,
        rotX: rotation.x,
        rotY: rotation.y,
        rotZ: rotation.z,
    }
}

export function resolveThreeJSRuntimeMeshAnimationItem(item: any) {
    if (!item) return item
    const desired = _getMeshAnimationDesired(item)
    return {
        ...item,
        position: {
            x: desired.posX,
            y: desired.posY,
            z: desired.posZ,
        },
        rotation: {
            x: desired.rotX,
            y: desired.rotY,
            z: desired.rotZ,
        },
        scale: {
            x: desired.scaleX,
            y: desired.scaleY,
            z: desired.scaleZ,
        },
        posX: desired.posX,
        posY: desired.posY,
        posZ: desired.posZ,
        rotX: desired.rotX,
        rotY: desired.rotY,
        rotZ: desired.rotZ,
        scaleX: desired.scaleX,
        scaleY: desired.scaleY,
        scaleZ: desired.scaleZ,
    }
}

export function resolveThreeJSRuntimeObjectEventItem(item: any) {
    if (!item) return item

    const click = item.click || {}
    const hover = item.hover || {}
    const press = item.press || {}
    const interaction = item.interaction || {}
    const drag = item.drag || {}
    const scroll = item.scroll || {}
    const clickEnabled = click.enabled === true
    const hoverEnabled = hover.enabled === true
    const pressEnabled = press.enabled === true
    const interactionEnabled = interaction.enabled === true
    const dragEnabled = drag.enabled === true
    const scrollEnabled = scroll.enabled === true

    let resolvedHoverEffect = "none"
    if (hoverEnabled) {
        resolvedHoverEffect = hover.effect
        if (!resolvedHoverEffect || resolvedHoverEffect === "none") {
            const transformScaleVal = hover.transformScale
            const transformPositionVal = hover.transformPosition
            const transformRotationVal = hover.transformRotation
            const hoverScaleVal = hover.scale

            const hasTransform =
                (transformScaleVal !== undefined &&
                    Number(transformScaleVal) !== 1) ||
                (transformPositionVal !== undefined &&
                    transformPositionVal !== "0,0,0") ||
                (transformRotationVal !== undefined &&
                    transformRotationVal !== "0,0,0")

            const hasScale =
                hoverScaleVal !== undefined &&
                Number(hoverScaleVal) !== 1 &&
                Number(hoverScaleVal) !== 0

            if (hasTransform) {
                resolvedHoverEffect = "transform"
            } else if (hasScale) {
                resolvedHoverEffect = "scale"
            } else {
                resolvedHoverEffect = "highlight"
            }
        }
    }

    return {
        ...item,
        __hasInteractionEvent:
            clickEnabled ||
            hoverEnabled ||
            pressEnabled ||
            interactionEnabled ||
            dragEnabled ||
            scrollEnabled,
        clickAction: clickEnabled ? (click.action ?? "none") : "none",
        clickUrl: click.url,
        clickUrlNewTab: click.newTab,
        clickTargetMesh: click.targetObject,
        clickColor: click.color,
        clickAnimClip: click.animName,
        clickAnimLoop: click.animLoop,
        clickAnimReverse: click.animReverse,
        onMeshClick: click.onClick,
        onAnimationComplete: click.onAnimationComplete,

        hoverEffect: resolvedHoverEffect,
        hoverColor: hover.color,
        hoverScale: hover.scale,
        hoverTransformPosition: hover.transformPosition,
        hoverTransformRotation: hover.transformRotation,
        hoverTransformScale: hover.transformScale,
        hoverSpeed: hover.speed,
        cursorStyle: hover.cursor,
        hoverTooltip: hover.tooltip,
        pressEnabled,
        pressTransformPosition: press.transformPosition,
        pressTransformRotation: press.transformRotation,
        pressTransformScale: press.transformScale,
        autoRotate: interactionEnabled ? interaction.autoRotate : false,
        meshAutoRotateSpeed: interaction.rotateSpeed,
        meshAutoRotateAxis: interaction.rotateAxis,
        mouseRotate: interactionEnabled ? interaction.mouseRotate : false,
        meshMouseRotateIntensity: interaction.mouseRotateIntensity,
        onMeshEnter: hover.onEnter,
        onMeshLeave: hover.onLeave,

        draggable: dragEnabled,
        dragPlane: drag.plane,
        dragSnapBack: drag.snapBack,
        dragConstraint: drag.constraint,
        onDragStart: drag.onStart,
        onDragEnd: drag.onEnd,

        scrollEnabled,
    }
}

export function _objectEventScrollAnimations(items: any[] = []) {
    return (items || [])
        .filter((item: any) => item?.meshName)
        .filter((item: any) => item?.scroll?.enabled)
        .map((item: any) => ({
            ...(item.scroll || {}),
            meshName: item.meshName,
            meshPath: item.meshPath,
            enabled: item.scroll?.enabled,
            scrollMatch: item.scroll?.match,
            scrollAnchorY: _resolveScrollAnchorY(item.scroll?.anchor, 0.5),
            scale: item.scroll?.scale,
            position: item.scroll?.position,
            rotation: item.scroll?.rotation,
            opacity: item.scroll?.opacity,
        }))
}

export function resolveThreeJSRuntimePosition(position: any, options: any = {}) {
    const width =
        typeof options === "number" ? options : Number(options?.width || 0)
    const forcedMobile =
        typeof options === "boolean" ? options : options?.useMobile
    const desktop = position?.desktop ?? position ?? {}
    const breakpoint = position?.breakpoint ?? 768
    const useMobile =
        forcedMobile !== undefined
            ? !!forcedMobile
            : !!width && width <= breakpoint
    if (!useMobile) return desktop

    const nestedMobile = position?.mobile ?? {}
    const mobileEnabled = position?.mobileEnabled ?? nestedMobile.enabled
    if (!mobileEnabled) return desktop

    const desktopFollowTarget = desktop.followTarget ?? {}
    const desktopScrollTarget = desktop.scrollTarget ?? {}
    const mobileFollowTarget = nestedMobile.followTarget ?? {}
    const mobileScrollTarget = nestedMobile.scrollTarget ?? {}

    return {
        ...desktop,
        ...nestedMobile,
        followLayer: nestedMobile.followLayer,
        followMatch: nestedMobile.followMatch,
        transitionEnabled: nestedMobile.transitionEnabled,
        transitionTargetId: nestedMobile.transitionTargetId,
        scrollTransform: true,
        scrollTransformMatch: nestedMobile.scrollTransformMatch,
        followTarget: {
            ...desktopFollowTarget,
            ...mobileFollowTarget,
        },
        scrollTarget: {
            ...desktopScrollTarget,
            ...mobileScrollTarget,
        },
        mobileEnabled,
    }
}

export function resolveThreeJSRuntimePositionConfig(props: any, options: any = {}) {
    const width =
        typeof options === "number" ? options : Number(options?.width || 0)
    const forcedMobile =
        typeof options === "boolean" ? options : options?.useMobile
    const position = props?.position || {}
    const nestedMobile = position?.mobile || {}
    const mobileBreakpoint = position?.breakpoint ?? 768
    const responsiveIsMobile =
        forcedMobile !== undefined
            ? !!forcedMobile &&
            !!(position?.mobileEnabled ?? nestedMobile.enabled)
            : !!width &&
            width <= mobileBreakpoint &&
            !!(position?.mobileEnabled ?? nestedMobile.enabled)
    const activePos =
        options?.activePosition ??
        resolveThreeJSRuntimePosition(position, {
            width,
            useMobile: forcedMobile,
        })
    const ui = props?.ui || {}
    const followMatch = String(activePos.followMatch ?? "").trim()
    const transformMatch = String(activePos.scrollTransformMatch ?? "").trim()
    const rawScrollTarget = activePos.scrollTarget ?? {}
    const scrollTargetPosition = _parseCommaVector3(rawScrollTarget.position, {
        x: rawScrollTarget.offX ?? 0,
        y: rawScrollTarget.offY ?? 0,
        z: rawScrollTarget.offZ ?? 0,
    })
    const scrollTargetRotation = _parseCommaVector3(rawScrollTarget.rotation, {
        x: rawScrollTarget.rotX ?? 0,
        y: rawScrollTarget.rotY ?? 0,
        z: rawScrollTarget.rotZ ?? 0,
    })
    const scrollTargetScaleRaw = rawScrollTarget.scale
    const scrollTarget = {
        offX: scrollTargetPosition.x,
        offY: scrollTargetPosition.y,
        offZ: scrollTargetPosition.z,
        rotX: scrollTargetRotation.x,
        rotY: scrollTargetRotation.y,
        rotZ: scrollTargetRotation.z,
        scale:
            scrollTargetScaleRaw !== undefined && scrollTargetScaleRaw !== 1
                ? scrollTargetScaleRaw
                : null,
    }
    const followEnabled = false
    const transformEnabled = true
    const transitionEnabled = false
    const transitionTargetId = ""
    const anchorX = 0.5
    const anchorY = _resolveScrollAnchorY(activePos.scrollAnchorY, 0.5)
    const followX = 0
    const followY = 0
    const followSmooth = 1

    return {
        activePosition: activePos,
        layoutPositionMode: activePos.mode ?? ui.positionMode ?? "relative",
        layoutLayerMatch: activePos.layerMatch ?? ui.positionLayerMatch ?? "",
        layoutTop: activePos.top ?? ui.positionTop ?? 0,
        layoutLeft: activePos.left ?? ui.positionLeft ?? 0,
        layoutRight: activePos.right ?? ui.positionRight ?? null,
        layoutBottom: activePos.bottom ?? ui.positionBottom ?? null,
        layoutZIndex: activePos.zIndex ?? ui.positionZIndex ?? 10,
        followEnabled,
        followLayerEnabled: followEnabled,
        scrollAnchorEnabled: followEnabled,
        followMatch,
        scrollAnchorMatch: followMatch,
        transformEnabled,
        scrollProgressTransformEnabled: transformEnabled,
        transformMatch,
        scrollTransformAnchorMatch: transformMatch,
        transitionEnabled,
        scrollAnchorTransitionEnabled: transitionEnabled,
        transitionTargetId,
        scrollAnchorTransitionTargetId: transitionTargetId,
        followX,
        followY,
        followSmooth,
        scrollAnchorStrengthX: followX,
        scrollAnchorStrengthY: followY,
        scrollAnchorSmoothing: followSmooth,
        anchorX,
        anchorY,
        scrollAnchorX: anchorX,
        scrollAnchorY: anchorY,
        scrollTarget,
        scrollAnchorRotationX: transformEnabled ? scrollTarget.rotX : 0,
        scrollAnchorRotationY: transformEnabled ? scrollTarget.rotY : 0,
        scrollAnchorRotationZ: transformEnabled ? scrollTarget.rotZ : 0,
        scrollProgressPositionX: scrollTarget.offX,
        scrollProgressPositionY: scrollTarget.offY,
        scrollProgressPositionZ: scrollTarget.offZ,
        scrollProgressScale: scrollTarget.scale,
        responsiveIsMobile,
    }
}

export function resolveThreeJSRuntimeInteractionConfig(props: any, options: any = {}) {
    const int = props?.interaction || {}
    const fx = props?.effects || {}
    const disableMouseRotation = !!options?.disableMouseRotation
    const movedInteractionProp = (key: string, defaultValue: any) => {
        if (!_hasOwnProp(props, key)) return int[key] ?? defaultValue
        return props[key]
    }
    const animationClip = movedInteractionProp("animClip", "")
    const animationMode = String(animationClip ?? "").trim() ? "single" : "all"
    return {
        enableOrbitControls: int.orbit ?? true,
        enableZoom: int.zoom ?? false,
        enableAutoRotate: int.autoRotate ?? true,
        autoRotateSpeed: int.rotateSpeed ?? 0.5,
        enableAnimation: true,
        animationMode,
        animationClip,
        animationSpeed: movedInteractionProp("animSpeed", 1),
        animationBlendDuration: 0.32,
        animationLoopMode: movedInteractionProp("animLoopMode", "repeat"),
        animationRestartOnSwitch: false,
        animationSyncPhase: true,
        animationWarp: false,
        animationModelHoverGate: int.modelHoverGate ?? false,
        animationWarmClips: true,
        enableMouseRotation: disableMouseRotation
            ? false
            : (int.mouseRotate ?? false),
        mouseRotationIntensity: int.mouseRotateIntensity ?? 0.1,
        enableParticles: int.particles ?? false,
        particleCount: int.particleCount ?? 2000,
        particleSize: int.particleSize ?? 0.05,
        particleColor: int.particleColor ?? "#00ffff",
        particleSpeed: int.particleSpeed ?? 1,
        particleSpread: int.particleSpread ?? 10,
        enableFloat: int.float ?? fx.float ?? true,
        floatAmplitude: int.floatAmp ?? fx.floatAmp ?? 0.8,
        floatSpeed: int.floatSpeed ?? fx.floatSpeed ?? 0.4,
        hasAnimationOnceCompleteHandler: !!props?.onAnimationOnceComplete,
        onAnimationOnceComplete: props?.onAnimationOnceComplete || null,
    }
}

export function resolveThreeJSRuntimeConfig(props: any, rectWidth = 0) {
    const tr = resolveThreeJSRuntimeTransform(props?.transform || {}, {
        width: rectWidth,
    })
    const cam = props?.camera || {}
    const env = props?.environment || {}
    const int = resolveThreeJSRuntimeInteractionConfig(props)
    const mat = props?.material || {}
    const fx = props?.effects || {}
    const extraLights = props?.extraLights ?? []
    const scenesRaw = props?.scenes || []
    const subSceneItems = scenesRaw.map((item: any) => {
        if (!item) return item
        const resolved = resolveThreeJSRuntimeSubSceneItem(item)
        const src = item.modelSource || "url"
        const modelUrl =
            src === "file" ? item.modelFile || "" : item.modelUrl || ""
        return { ...resolved, modelUrl }
    })

    const cfg = {
        autoMergeMeshes: props?.autoMergeMeshes ?? false,
        modelScale: tr.scale ?? 1,
        modelOffsetX: tr.offX ?? 0,
        modelOffsetY: tr.offY ?? 0,
        modelOffsetZ: tr.offZ ?? 0,
        modelRotationX: tr.rotX ?? 0,
        modelRotationY: tr.rotY ?? 0,
        modelRotationZ: tr.rotZ ?? 0,
        cameraType: cam.cameraType ?? "perspective",
        cameraPositionX: cam.x ?? -1,
        cameraPositionY: cam.y ?? 2,
        cameraPositionZ: cam.z ?? 10,
        orthoZoom: cam.orthoZoom ?? 1,
        stereoEyeSep: cam.stereoEyeSep ?? 0.064,
        fov: cam.fov ?? 35,
        backgroundColor: env.bgColor ?? "#1c1c1c",
        transparentBackground: env.transparent ?? true,
        enableEnvironment: env.enabled ?? true,
        environmentType: env.type ?? "procedural",
        environmentPreset: env.preset ?? "studio",
        hdriPreset: env.hdriPreset ?? "studio_small_09",
        customHdriUrl: env.customUrl ?? "",
        environmentIntensity: env.intensity ?? 1,
        environmentRotationY: Number(props?.envRotationY ?? env.rotY ?? 0) || 0,
        environmentRotationX: Number(props?.envRotationX ?? env.rotX ?? 0) || 0,
        showEnvironmentBackground: env.showBg ?? false,
        ambientLightIntensity: env.ambient ?? 0.5,
        directionalLightIntensity: env.dirIntensity ?? 1,
        directionalLightColor: env.dirColor ?? "#ffffff",
        dirLightPosX: env.dirPosX ?? 5,
        dirLightPosY: env.dirPosY ?? 10,
        dirLightPosZ: env.dirPosZ ?? 7,
        enableShadows: env.shadows ?? false,
        shadowMapSize: parseInt(env.shadowSize ?? "1024", 10) || 1024,
        shadowBias: env.shadowBias ?? -0.0001,
        shadowNormalBias: env.shadowNormalBias ?? 0.02,
        extraLights,
        ...int,
        materialPreset: mat.preset ?? "none",
        sketchBaseColor: mat.sketchBaseColor ?? "#f4f2ec",
        sketchLineColor: mat.sketchLineColor ?? "#050505",
        sketchLineThickness: mat.sketchLineThickness ?? 0.045,
        sketchSteps: mat.sketchSteps ?? 3,
        animeLineThickness: mat.animeLineThickness ?? 0.06,
        animeLineColor: mat.animeLineColor ?? "#050505",
        animeLineEmissiveColor: mat.animeLineEmissiveColor ?? "#ffffff",
        animeLineEmissiveIntensity: mat.animeLineEmissiveIntensity ?? 0.08,
        overrideMaterial: mat.override ?? false,
        metalness: mat.metalness ?? 0,
        roughness: mat.roughness ?? 0.5,
        clearcoat: mat.clearcoat ?? 0,
        clearcoatRoughness: mat.clearcoatRoughness ?? 0,
        transmission: mat.transmission ?? 0,
        thickness: mat.thickness ?? 0,
        ior: mat.ior ?? 1.5,
        iridescence: mat.iridescence ?? 0,
        iridescenceIOR: mat.iridescenceIOR ?? 1.3,
        sheen: mat.sheen ?? 0,
        sheenRoughness: mat.sheenRoughness ?? 0.3,
        sheenColor: mat.sheenColor ?? "#ffffff",
        envMapIntensity: mat.envMapIntensity ?? 1,
        reflectivity: mat.reflectivity ?? 0.5,
        emissiveIntensity: mat.emissiveIntensity ?? 0,
        emissiveColor: mat.emissiveColor ?? "#000000",
        opacity: mat.opacity ?? 1,
        wireframe: mat.wireframe ?? false,
        materialTransitionDuration: mat.transitionDuration ?? 0.3,
        bloomEnabled: fx.bloom ?? false,
        bloomStrength: fx.bloomStr ?? 0.5,
        bloomThreshold: fx.bloomThresh ?? 0.8,
        bloomRadius: fx.bloomRad ?? 0.5,
        toneMapping: fx.toneMapping ?? "aces",
        exposure: fx.exposure ?? 1.2,
        enableFXAA: fx.fxaa ?? true,
        enableColorGrading: fx.colorGrading ?? false,
        brightness: fx.brightness ?? 0,
        contrast: fx.contrast ?? 1,
        saturation: fx.saturation ?? 1,
        enableVignette: fx.vignette ?? false,
        vignetteOffset: fx.vigOffset ?? 1,
        vignetteDarkness: fx.vigDark ?? 1.2,
        enableChromaticAberration: fx.chromAberr ?? false,
        chromaticAberrationStrength: fx.chromStr ?? 0.005,
        enableFilmGrain: fx.filmGrain ?? false,
        filmGrainIntensity: fx.grainInt ?? 0.04,
        enablePixelate: fx.pixelate ?? false,
        pixelateShape: fx.pixelShape ?? "rectangle",
        pixelateSize: fx.pixelSize ?? 23,
        pixelateStretch: fx.pixelStretch ?? 0,
        // Pixelate keeps the source colors and uses solid cells by default.
        // Keep the fields in the resolved config for compatibility with older
        // saved component data, but do not allow legacy values to re-enable
        // the removed gap/color-trim behavior.
        pixelateGap: 0,
        pixelateColorTrim: 0,
        pixelateAverageColor: fx.pixelAverageColor ?? 42,
        pixelateDissolveMode: fx.pixelDissolveMode ?? "dropout",
        pixelateDissolve: fx.pixelDissolve ?? 0,
        pixelateFalloff: fx.pixelFalloff ?? 0,
        pixelateKnockout: fx.pixelKnockout ?? true,
        // Kept as compatibility fields for older saved component data.
        pixelateNormalEdgeStrength: fx.pixelNormalEdge ?? 0.3,
        pixelateDepthEdgeStrength: fx.pixelDepthEdge ?? 0.4,
        enableSSAO: fx.ssao ?? false,
        ssaoRadius: fx.ssaoRadius ?? 8,
        ssaoMinDistance: fx.ssaoMinDist ?? 0.001,
        ssaoMaxDistance: fx.ssaoMaxDist ?? 0.1,
        enableDOF: cam.dof ?? false,
        dofFocus: cam.dofFocus ?? 10,
        dofAperture: cam.dofAperture ?? 0.025,
        dofMaxBlur: cam.dofMaxBlur ?? 0.01,
        subSceneItems,
    }

    cfg._materialHash = [
        cfg.materialPreset,
        cfg.overrideMaterial,
        cfg.metalness,
        cfg.roughness,
        cfg.clearcoat,
        cfg.clearcoatRoughness,
        cfg.transmission,
        cfg.thickness,
        cfg.ior,
        cfg.iridescence,
        cfg.iridescenceIOR,
        cfg.sheen,
        cfg.sheenRoughness,
        cfg.sheenColor,
        cfg.envMapIntensity,
        cfg.emissiveIntensity,
        cfg.emissiveColor,
        cfg.reflectivity,
        cfg.opacity,
        cfg.wireframe,
    ].join("|")
    cfg._lightingHash = [
        cfg.ambientLightIntensity,
        cfg.directionalLightIntensity,
        cfg.directionalLightColor,
        cfg.dirLightPosX,
        cfg.dirLightPosY,
        cfg.dirLightPosZ,
        cfg.enableShadows,
        cfg.shadowMapSize,
        cfg.shadowBias,
        cfg.shadowNormalBias,
        JSON.stringify(
            (cfg.extraLights || []).map((light: any) => ({
                enabled: light?.enabled,
                type: light?.lightType,
                color: light?.color,
                intensity: light?.intensity,
                posX: light?.posX,
                posY: light?.posY,
                posZ: light?.posZ,
                distance: light?.distance,
                decay: light?.decay,
                angle: light?.angle,
                penumbra: light?.penumbra,
                targetX: light?.targetX,
                targetY: light?.targetY,
                targetZ: light?.targetZ,
                castShadow: light?.castShadow,
            }))
        ),
    ].join("|")
    cfg._envHash = [
        cfg.enableEnvironment,
        cfg.environmentType,
        cfg.environmentPreset,
        cfg.hdriPreset,
        cfg.customHdriUrl,
        cfg.environmentIntensity,
        cfg.showEnvironmentBackground,
        cfg.transparentBackground,
        cfg.backgroundColor,
    ].join("|")
    cfg._effectsHash = [
        cfg.bloomEnabled,
        cfg.bloomStrength,
        cfg.bloomThreshold,
        cfg.bloomRadius,
        cfg.toneMapping,
        cfg.exposure,
        cfg.enableFXAA,
        cfg.enableColorGrading,
        cfg.brightness,
        cfg.contrast,
        cfg.saturation,
        cfg.enableVignette,
        cfg.vignetteOffset,
        cfg.vignetteDarkness,
        cfg.enableChromaticAberration,
        cfg.chromaticAberrationStrength,
        cfg.enableFilmGrain,
        cfg.filmGrainIntensity,
        cfg.enablePixelate,
        cfg.pixelateShape,
        cfg.pixelateSize,
        cfg.pixelateStretch,
        cfg.pixelateGap,
        cfg.pixelateColorTrim,
        cfg.pixelateAverageColor,
        cfg.pixelateDissolveMode,
        cfg.pixelateDissolve,
        cfg.pixelateFalloff,
        cfg.pixelateKnockout,
        cfg.enableSSAO,
        cfg.ssaoRadius,
        cfg.ssaoMinDistance,
        cfg.ssaoMaxDistance,
        cfg.enableDOF,
        cfg.dofFocus,
        cfg.dofAperture,
        cfg.dofMaxBlur,
    ].join("|")
    cfg._sceneConfigHash = [
        cfg._materialHash,
        cfg._lightingHash,
        cfg._envHash,
        cfg._effectsHash,
    ].join("||")

    return cfg
}

export function resolveThreeJSRuntimeAppearConfig(props: any) {
    const { dissolveTransition: dissolve = {} } = props
    const transform = dissolve.transform ?? {}
    const noise = dissolve.noise ?? {}
    const edge = dissolve.edge ?? {}
    const particles = dissolve.particles ?? {}

    const duration = dissolve.duration ?? 1.5
    const appearPosition = _parseCommaVector3(transform.position, {
        x: transform.offX ?? 0,
        y: transform.offY ?? 0,
        z: transform.offZ ?? 0,
    })
    const appearRotation = _parseCommaVector3(transform.rotation, {
        x: transform.rotX ?? 0,
        y: transform.rotY ?? 0,
        z: transform.rotZ ?? 0,
    })
    const offX = appearPosition.x
    const offY = appearPosition.y
    const offZ = appearPosition.z
    const scale = transform.scale ?? 1
    const rotX = appearRotation.x
    const rotY = appearRotation.y
    const rotZ = appearRotation.z

    const blurReveal = dissolve.blurReveal ?? false
    const blurRevealIntensity = dissolve.blurIntensity ?? 12
    const blurRevealDuration = dissolve.blurDuration ?? 0.8

    const noiseScale = noise.noiseScale ?? 0.25
    const amplitude = noise.amplitude ?? 16
    const edgeWidth = edge.edgeWidth ?? 0.8
    const emissiveColor = edge.emissiveColor ?? "#ff7a32"
    const emissiveIntensity = edge.emissiveIntensity ?? 3

    return {
        dissolveEnabled: dissolve.enabled ?? true,
        appearReplay: props?.appearReplay ?? dissolve.replay ?? true,
        duration,
        dissolveDuration: duration,
        offX,
        offY,
        offZ,
        scale,
        rotX,
        rotY,
        rotZ,
        appearOffsetX: offX,
        appearOffsetY: offY,
        appearOffsetZ: offZ,
        appearScale: scale,
        appearRotateX: rotX,
        appearRotateY: rotY,
        appearRotateZ: rotZ,
        blurReveal,
        blurRevealIntensity,
        blurRevealDuration,
        noiseScale,
        amplitude,
        dissolveNoiseScale: noiseScale,
        dissolveAmplitude: amplitude,
        edgeWidth,
        emissiveColor,
        emissiveIntensity,
        dissolveEdgeWidth: edgeWidth,
        dissolveEmissiveColor: emissiveColor,
        dissolveEmissiveIntensity: emissiveIntensity,
        dissolveParticlesEnabled: particles.enabled ?? true,
        dissolveParticleBaseSize: particles.baseSize ?? 80,
        dissolveParticleColor: particles.color ?? "#ff7a32",
        dissolveParticleSpeed: particles.speed ?? 0.02,
        dissolveParticleWaveAmp: particles.waveAmp ?? 0,
        dissolveParticleVelX: particles.velX ?? 2.5,
        dissolveParticleVelY: particles.velY ?? 2.0,
        dissolveParticleMaxCount: particles.maxCount ?? 8000,
        progressiveLoading: dissolve.progressive ?? false,
        progressiveFadeDuration: dissolve.progressiveFade ?? 0.8,
    }
}

export function buildThreeJSRuntimeSettings(props: any, options: any = {}) {
    const rectWidth =
        options?.rectWidth ?? options?.width ?? options?.clientWidth ?? 0
    const runtimeCfg = resolveThreeJSRuntimeConfig(props, rectWidth)
    const positionCfg = resolveThreeJSRuntimePositionConfig(props, {
        width: rectWidth,
        useMobile: options?.useMobile,
    })
    const appearCfg = resolveThreeJSRuntimeAppearConfig(props)
    const perf = props?.performance || {}
    const ui = props?.ui || {}
    const meshInteractionsRaw = (props?.meshInteractions ?? []).map(
        resolveThreeJSRuntimeObjectEventItem
    )
    const meshAnimationsRaw = [
        ...(props?.meshAnimations ?? []),
        ..._objectEventScrollAnimations(props?.meshInteractions ?? []),
    ].map(resolveThreeJSRuntimeMeshAnimationItem)
    const meshAnimationItems = (meshAnimationsRaw || []).filter(
        (anim: any) => anim?.enabled && anim?.meshName
    )
    const meshAnimationsLookupKey = JSON.stringify(
        meshAnimationItems.map((anim: any) =>
            anim?.meshPath ? `path:${anim.meshPath}` : `name:${String(anim.meshName).trim().toLowerCase()}`
        )
    )
    const meshInteractionItems = (meshInteractionsRaw || []).filter(
        (ic: any) => ic?.meshName && (ic.__hasInteractionEvent ?? true)
    )
    const meshInteractionTargetNames = meshInteractionItems.map((ic: any) =>
        String(ic.meshName).trim().toLowerCase()
    )
    const meshInteractionLookupKey = JSON.stringify(
        meshInteractionItems.map((ic: any) =>
            ic?.meshPath ? `path:${ic.meshPath}` : `name:${String(ic.meshName).trim().toLowerCase()}`
        )
    )
    const meshObjectTransformItems = meshInteractionsRaw.filter(
        (ic: any) => ic?.meshPath && ic?.transform && Object.keys(ic.transform).length > 0
    )
    const meshObjectTransformKey = JSON.stringify(
        meshObjectTransformItems.map((ic: any) => ({ meshPath: ic.meshPath, transform: ic.transform }))
    )
    const meshInteractionRuntimeKey = JSON.stringify(
        meshInteractionItems.map((ic: any) => ({
            meshName: ic?.meshName,
            meshPath: ic?.meshPath,
            transform: ic?.transform,
            clickAction: ic?.clickAction,
            clickUrl: ic?.clickUrl,
            clickTargetMesh: ic?.clickTargetMesh,
            clickColor: ic?.clickColor,
            clickAnimClip: ic?.clickAnimClip,
            clickAnimLoop: ic?.clickAnimLoop,
            clickAnimReverse: ic?.clickAnimReverse,
            autoRotate: ic?.autoRotate,
            meshAutoRotateSpeed: ic?.meshAutoRotateSpeed,
            meshAutoRotateAxis: ic?.meshAutoRotateAxis,
            mouseRotate: ic?.mouseRotate,
            meshMouseRotateIntensity: ic?.meshMouseRotateIntensity,
            hoverEffect: ic?.hoverEffect,
            hoverColor: ic?.hoverColor,
            hoverScale: ic?.hoverScale,
            hoverTransformPosition: ic?.hoverTransformPosition,
            hoverTransformRotation: ic?.hoverTransformRotation,
            hoverTransformScale: ic?.hoverTransformScale,
            hoverSpeed: ic?.hoverSpeed,
            pressEnabled: ic?.pressEnabled,
            pressTransformPosition: ic?.pressTransformPosition,
            pressTransformRotation: ic?.pressTransformRotation,
            pressTransformScale: ic?.pressTransformScale,
            draggable: ic?.draggable,
            dragPlane: ic?.dragPlane,
            dragSnapBack: ic?.dragSnapBack,
            dragConstraint: ic?.dragConstraint,
        }))
    )
    const qualityMode = options?.qualityMode || "balanced"
    const isMobile = !!positionCfg.responsiveIsMobile
    const performanceMode = perf.mode ?? ui.performanceMode ?? true
    const performanceMaxPixelCount =
        perf.maxPixelCount ?? ui.performanceMaxPixelCount ?? 3000000
    const useMobilePerfProfile = performanceMode && isMobile
    const isPerformance = qualityMode === "performance"
    const isBalanced = qualityMode === "balanced"
    const qualityMaxPixelBudget = isPerformance
        ? isMobile
            ? 1200000
            : 1800000
        : isBalanced
            ? isMobile
                ? 1800000
                : 2400000
            : isMobile
                ? 1800000
                : performanceMaxPixelCount
    const effectivePerformanceMaxPixelCount =
        qualityMaxPixelBudget > 0
            ? performanceMaxPixelCount > 0
                ? Math.min(performanceMaxPixelCount, qualityMaxPixelBudget)
                : qualityMaxPixelBudget
            : performanceMaxPixelCount
    const effectiveShadowMapSize = isPerformance
        ? Math.min(runtimeCfg.shadowMapSize, 256)
        : isBalanced || useMobilePerfProfile
            ? Math.min(runtimeCfg.shadowMapSize, 512)
            : runtimeCfg.shadowMapSize
    const effectiveBloomEnabled = isPerformance
        ? false
        : runtimeCfg.bloomEnabled
    const effectiveEnableSSAO =
        isPerformance || isBalanced || useMobilePerfProfile
            ? false
            : runtimeCfg.enableSSAO
    const effectiveEnableDOF =
        isPerformance || isBalanced || useMobilePerfProfile
            ? false
            : runtimeCfg.enableDOF
    const effectiveEnableChromaticAberration =
        isPerformance || useMobilePerfProfile
            ? false
            : runtimeCfg.enableChromaticAberration
    const effectiveEnableFilmGrain =
        isPerformance || useMobilePerfProfile
            ? false
            : runtimeCfg.enableFilmGrain
    const effectiveParticleCount = isPerformance
        ? Math.min(runtimeCfg.particleCount, 500)
        : useMobilePerfProfile || isBalanced
            ? Math.min(runtimeCfg.particleCount, 1000)
            : runtimeCfg.particleCount
    const effectiveDissolveParticleMaxCount = isPerformance
        ? Math.min(appearCfg.dissolveParticleMaxCount, 1200)
        : useMobilePerfProfile || isBalanced
            ? Math.min(appearCfg.dissolveParticleMaxCount, 3000)
            : appearCfg.dissolveParticleMaxCount

    const cfg = {
        ...runtimeCfg,
        ...positionCfg,
        ...appearCfg,
        extraLights: runtimeCfg.extraLights ?? props?.extraLights ?? [],
        shadowMapSize: effectiveShadowMapSize,
        bloomEnabled: effectiveBloomEnabled,
        enableSSAO: effectiveEnableSSAO,
        enableDOF: effectiveEnableDOF,
        enableChromaticAberration: effectiveEnableChromaticAberration,
        enableFilmGrain: effectiveEnableFilmGrain,
        particleCount: effectiveParticleCount,
        dissolveParticleMaxCount: effectiveDissolveParticleMaxCount,
        performanceMode,
        webglActive: perf.webglActive ?? ui.webglActive ?? true,
        performanceDprCap:
            options?.dprCapDesktop ??
            perf.dprCap ??
            ui.performanceDprCap ??
            (performanceMode ? 1.5 : 2),
        performanceMobileDprCap:
            options?.dprCapMobile ??
            perf.mobileDprCap ??
            ui.performanceMobileDprCap ??
            1.5,
        performanceMaxPixelCount: effectivePerformanceMaxPixelCount,
        performanceLazyWebgl: perf.lazyWebgl ?? ui.performanceLazyWebgl ?? true,
        performancePauseHidden:
            options?.pauseHidden ??
            perf.pauseHidden ??
            ui.performancePauseHidden ??
            true,
        performancePauseOffscreen:
            options?.pauseOffscreen ??
            perf.pauseOffscreen ??
            ui.performancePauseOffscreen ??
            true,
        performanceStats: perf.stats ?? ui.performanceStats ?? false,
        performanceAntialias: isPerformance
            ? false
            : (perf.antialias ?? ui.performanceAntialias ?? !performanceMode),
        showControls: ui.showHints ?? true,
        showMeshHelper: ui.meshHelper ?? false,
        showStatsMonitor: ui.statsMonitor ?? false,
        statsMonitorPanel: ui.statsPanel ?? "fps",
        showGrid: ui.showGrid ?? false,
        showGridSize: ui.gridSize ?? 10,
        showGridDivisions: ui.gridDivisions ?? 10,
        showGridColor1: ui.gridColor1 ?? "rgba(255,255,255,0.25)",
        showGridColor2: ui.gridColor2 ?? "rgba(255,255,255,0.1)",
        showAxes: ui.showAxes ?? false,
        showAxesSize: ui.axesSize ?? 3,
        showModelAxes: ui.showModelAxes ?? false,
        showModelAxesSize: ui.modelAxesSize ?? 2,
        stopMotionInEditor: ui.stopInEditor ?? false,
        enableScrollAnimation: true,
        scrollSmoothing: _SCROLL_SMOOTHING_SPEED,
        responsiveIsMobile: isMobile,
        meshAnimations: meshAnimationsRaw,
        meshAnimationItems,
        hasEnabledMeshAnimations: meshAnimationItems.length > 0,
        meshAnimationLookupKey: meshAnimationsLookupKey,
        meshInteractions: meshInteractionsRaw,
        meshInteractionItems,
        meshInteractionTargetNames,
        meshObjectTransformItems,
        meshObjectTransformKey,
        hasEnabledMeshInteractions: meshInteractionItems.length > 0,
        hasDraggableMeshInteractions: meshInteractionItems.some(
            (ic: any) => !!ic?.draggable
        ),
        meshInteractionLookupKey,
        meshInteractionRuntimeKey,
    }

    cfg._materialHash = materialHash(cfg)
    cfg._lightingHash = lightingHash(cfg)
    cfg._envHash = envHash(cfg)
    cfg._effectsHash = effectsHash(cfg)
    cfg._sceneConfigHash = sceneConfigHash(cfg)
    cfg._animationReplayHash = appearReplayHash(cfg)
    return cfg
}
